import{_ as s,c as e,o as t,ag as i}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Install a bootloader","description":"","frontmatter":{},"headers":[],"relativePath":"installation/install-bootloader.md","filePath":"installation/install-bootloader.md","lastUpdated":1792149212000}'),n={name:"installation/install-bootloader.md"};function o(l,a,p,h,r,d){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="install-a-bootloader" tabindex="-1">Install a bootloader <a class="header-anchor" href="#install-a-bootloader" aria-label="Permalink to &quot;Install a bootloader&quot;">​</a></h1><p>Finish system configuration, desktop selection and driver installation first. Choose <strong>one</strong> bootloader: systemd-boot or GRUB for UEFI, GRUB for BIOS. These commands run inside the chroot.</p><h2 id="generate-the-initramfs" tabindex="-1">Generate the initramfs <a class="header-anchor" href="#generate-the-initramfs" aria-label="Permalink to &quot;Generate the initramfs&quot;">​</a></h2><p>For the encrypted layout, first complete <a href="/encryption/#configure-the-initramfs">Configure the initramfs</a>, then return here. For an unencrypted installation, keep the current default hooks in <code>/etc/mkinitcpio.conf</code>.</p><p>Confirm <code>/etc/vconsole.conf</code> contains your keyboard layout and the correct CPU microcode package is installed. Generate images for all installed kernels:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkinitcpio</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -P</span></span></code></pre></div><p>Resolve any errors before continuing. On UEFI, check that <code>/boot</code> is the mounted ESP and contains <code>vmlinuz-linux</code> and <code>initramfs-linux.img</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findmnt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /boot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /boot</span></span></code></pre></div><h2 id="uefi-systemd-boot" tabindex="-1">UEFI: systemd-boot <a class="header-anchor" href="#uefi-systemd-boot" aria-label="Permalink to &quot;UEFI: systemd-boot&quot;">​</a></h2><p>Install the boot manager included with systemd:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bootctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --esp-path=/boot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nano</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /boot/loader/loader.conf</span></span></code></pre></div><p>Use:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>default arch.conf</span></span>
<span class="line"><span>timeout 4</span></span>
<span class="line"><span>editor no</span></span></code></pre></div><p>For an unencrypted root filesystem, obtain its filesystem UUID:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blkid</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UUID</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> value</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1p2</span></span></code></pre></div><p>Create <code>/boot/loader/entries/arch.conf</code>, replacing <code>ROOT_FILESYSTEM_UUID</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>title Arch Linux</span></span>
<span class="line"><span>linux /vmlinuz-linux</span></span>
<span class="line"><span>initrd /initramfs-linux.img</span></span>
<span class="line"><span>options root=UUID=ROOT_FILESYSTEM_UUID rw</span></span></code></pre></div><p>The microcode hook includes installed CPU microcode in the initramfs, so this entry does not need a separate microcode image. Keep comments on separate lines in boot entry files.</p><p>For the encrypted layout, replace the entire <code>options</code> line with the following, using the UUID reported by <code>cryptsetup luksUUID</code> for the outer LUKS partition:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>options rd.luks.name=LUKS_UUID=cryptroot root=/dev/mapper/main-root rw</span></span></code></pre></div><p>Inspect the installed entry:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bootctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --esp-path=/boot</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>See <a href="https://wiki.archlinux.org/title/Systemd-boot" target="_blank" rel="noreferrer">systemd-boot</a> for boot manager updates, additional kernels and dual boot. Each extra kernel needs its own entry unless you configure automatic entry management.</p><h2 id="grub" tabindex="-1">GRUB <a class="header-anchor" href="#grub" aria-label="Permalink to &quot;GRUB&quot;">​</a></h2><h3 id="uefi-installation" tabindex="-1">UEFI installation <a class="header-anchor" href="#uefi-installation" aria-label="Permalink to &quot;UEFI installation&quot;">​</a></h3><p>The ESP must be mounted at <code>/boot</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> efibootmgr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grub-install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=x86_64-efi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --efi-directory=/boot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootloader-id=GRUB</span></span></code></pre></div><h3 id="bios-installation" tabindex="-1">BIOS installation <a class="header-anchor" href="#bios-installation" aria-label="Permalink to &quot;BIOS installation&quot;">​</a></h3><p>Use the whole disk, not a partition. A GPT disk also needs the unformatted BIOS boot partition described on the partitioning page:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grub-install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=i386-pc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/nvme0n1</span></span></code></pre></div><h3 id="encrypted-root" tabindex="-1">Encrypted root <a class="header-anchor" href="#encrypted-root" aria-label="Permalink to &quot;Encrypted root&quot;">​</a></h3><p>For the UEFI encrypted layout in this guide, edit <code>/etc/default/grub</code> and set the following, replacing <code>LUKS_UUID</code> with the outer partition&#39;s LUKS UUID. Preserve any other options you deliberately configured:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRUB_CMDLINE_LINUX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rd.luks.name=LUKS_UUID=cryptroot root=/dev/mapper/main-root&quot;</span></span></code></pre></div><p>GRUB reads the unencrypted <code>/boot</code>; the initramfs unlocks root. This layout does not require <code>GRUB_ENABLE_CRYPTODISK</code>.</p><h3 id="other-operating-systems" tabindex="-1">Other operating systems <a class="header-anchor" href="#other-operating-systems" aria-label="Permalink to &quot;Other operating systems&quot;">​</a></h3><p>If you want GRUB to detect another installed OS, install <code>os-prober</code>, mount the relevant OS filesystems as described in the <a href="https://wiki.archlinux.org/title/GRUB#Detecting_other_operating_systems" target="_blank" rel="noreferrer">GRUB documentation</a>, and set this in <code>/etc/default/grub</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRUB_DISABLE_OS_PROBER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span></code></pre></div><h3 id="generate-the-configuration" tabindex="-1">Generate the configuration <a class="header-anchor" href="#generate-the-configuration" aria-label="Permalink to &quot;Generate the configuration&quot;">​</a></h3><p>For every GRUB installation, finish with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grub-mkconfig</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /boot/grub/grub.cfg</span></span></code></pre></div><p>Check for errors and confirm it found the installed kernel. Regenerate this file after changing GRUB settings or adding a kernel.</p>`,41)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
